<div class="toolbar"><form class="filterbar" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search action, entity or user…"><button class="btn" type="submit">Search</button></form></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Action</th><th>User</th><th>Entity</th><th>Context</th><th>Time</th></tr></thead><tbody><?php foreach($items as $a):?><tr><td><strong><?= e($a['action']) ?></strong></td><td><?= e($a['user_name']??'System') ?><small class="table-sub"><?= e($a['user_email']??'') ?></small></td><td><?= e($a['entity_type']??'—') ?><?= $a['entity_id']?' #'.(int)$a['entity_id']:'' ?></td><td><code class="context-code"><?= e(mb_substr((string)($a['context_json']??''),0,160)) ?></code></td><td class="muted"><?= e($a['created_at']) ?></td></tr><?php endforeach;?><?php if(!$items):?><tr><td colspan="5" class="empty-cell">No activity found.</td></tr><?php endif;?></tbody></table></div></section>